        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "farei o possível para não amar demais as pessoas, sobretudo por causa das pessoas. Às vezes o amor que se dá pesa, quase como responsabilidade na pessoa que o recebe. Eu tenho essa tendência geral para exagerar, e resolvi tentar não exigir dos outros senão o mínimo. É uma forma de paz...", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Suponho que me entender não é uma questão de inteligência e sim de sentir, de entrar em contato. Ou toca, ou não toca!", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Acho que sábado é a rosa da semana.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Amor é não ter. Inclusive amor é a desilusão do que se pensava que era amor. E não é prêmio por isso não envaidece", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Amor é quando é concedido participar um pouco mais. Poucos querem o amor, porque amor é a grande desilusão de tudo o mais. E poucos suportam perder todas as outras ilusões", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Fique de vez em quando sozinho, senão você será submergido. Até o amor excessivo dos outros pode submergir uma pessoa.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Passei a minha vida tentando corrigir os erros que cometi na minha ânsia de acertar. Ao tentar corrigir um erro, eu cometia outro. Sou uma culpada inocente.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Até cortar os próprios defeitos pode ser perigoso. Nunca se sabe qual é o defeito que sustenta nosso edifício inteiro.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Ela acreditava em anjos e, porque acreditava, eles existiam.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Mas há a vida/ que é para ser intensamente vivida,/ há o amor./ Que tem que ser vivido/ até a última gota./ Sem nenhum medo./ Não mata.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "nem entendo aquilo que entendo: pois estou infinitamente maior do que eu mesma, e não me alcanço.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "O que verdadeiramente somos é aquilo que o impossível cria em nós.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Que medo alegre/ o de te esperar", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "A eternidade é o estado das coisas neste momento.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Aliás - descubro eu agora - eu também não faço a menor falta, e até o que escrevo um outro escreveria.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Enquanto eu tiver perguntas e não houver respostas continuarei a escrever.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Escrevo por ter nada a fazer no mundo: sobrei e não há lugar para mim na terra dos homens.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Não tenho medo nem das chuvas tempestivas nem das grandes ventanias soltas. Pois eu também sou o escuro da noite.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Não se pode dar uma prova de existência do que é mais verdadeiro, o jeito é acreditar. Acreditar chorando.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Que ninguém se engane: só se consegue a simplicidade através de muito trabalho.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Quem não é um acaso na vida?", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Talvez a pergunta vazia fosse apenas para que um dia alguém não viesse a dizer que ela nem ao menos havia perguntado. Por falta de quem lhe respondesse ela mesma parecia se ter respondido: é assim porque é assim.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "A saudade é a prova que o passado valeu a pena.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "A vida é dura para quem é mole.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "A vida é igual em toda a parte e o que é necessário é a gente ser a gente.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Com Deus a gente também pode abrir caminho pela violência. Ele mesmo quando precisa mais especialmente de um de nós, Ele nos escolhe e nos violenta.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Dá-me a tua mão desconhecida que a vida está me doendo e eu não sei como falar- a realidade é delicada demais, só a realidade é delicada, minha irrealidade e minha imaginação são mais pesadas.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Eu escrevo sem esperança de que o que eu escrevo altere qualquer coisa. Não altera em nada... Porque no fundo a gente não está querendo alterar as coisas. A gente está querendo desabrochar de um modo ou de outro...", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "É preciso coragem. Uma coragem danada. Muita coragem é o que eu preciso. Sinto-me tão desamparada, preciso tanto de proteção...porque parece que sou portadora de uma coisa muito pesada. Sei lá porque escrevo! Que fatalidade é esta?", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "É quase impossível evitar o excesso de amor que um bobo provoca. É que só o bobo é capaz de excesso de amor. E só o amor faz o bobo.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Escrever é procurar entender, é procurar reproduzir o irreproduzível, é sentir até o último fim o sentimento que permaneceria apenas vago e sufocador. Escrever é também abençoar uma vida que não foi abençoada", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Escrevo porque encontro nisso um prazer que não consigo traduzir. Não sou pretensiosa. Escrevo para mim, para que eu sinta a minha alma falando e cantando, às vezes chorando...", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Minha liberdade é escrever. A palavra é o meu domínio sobre o mundo.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Não quero ter a terrível limitação de quem vive apenas do que é possível fazer sentido. Eu não: quero é uma verdade inventada.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Nem todos chegam a fracassar porque é tão trabalhoso, é preciso antes subir penosamente até enfim atingir a altura de poder cair.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "O que é verdadeiramente imoral é ter desistido de si mesmo.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "E porque minha alma é tão ilimitada que já não sou eu, e porque ela está tão além de mim - é que sempre sou remota a mim mesma, sou-me inalcançável como me é inalcançável um astro...", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "O mistério do destino humano é que somos fatais, mas temos a liberdade de cumprir ou não o nosso fatal: de nós depende realizarmos o nosso destino fatal... mas de mim depende eu vir a ser o que fatalmente sou...", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Somos livres, e este é o inferno.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Viajo porque gosto, volto porque te amo.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Vida e morte foram minhas, e eu fui monstruosa, minha coragem foi a de um sonâmbulo que simplesmente vai.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Vocação é diferente de talento. Pode-se ter vocação e não ter talento, isto é, pode-se ser chamado e não saber como ir", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Sempre conservei uma aspa à esquerda e outra à direita de mim.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Só trabalho com achados e perdidos.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Todo cidadão tem o direito de ir e vir. Desde que seja a pé, de outra forma paga pedágio.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Quando me comunico com criança é fácil porque sou muito maternal. Quando me comunico com o adulto, na verdade, estou me comunicando com o mais secreto de mim mesma.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "O adulto é triste e solitário.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "A criança tem a fantasia solta.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Agora sei: sou só. Eu e minha liberdade que não sei usar. Grande responsabilidade da solidão. Quem não é perdido não conhece a liberdade e não a ama.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "A coragem de viver: deixo oculto o que preciso ser oculto e precisa irradiar-se em segredo. Calo-me.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "E ninguém é eu. E ninguém é você. Esta é a solidão.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "É uma infâmia nascer para morrer não se sabe quando nem onde", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Ouve-me. Ouve o meu silêncio. O que falo nunca é o que falo e, sim, outra coisa. (...) Capta a “outra coisa” porque eu mesma não posso.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Minha verdade espantada é que eu sempre estive só de ti e não sabia. Agora sei: sou só. Eu e minha liberdade que não sei usar. Grande responsabilidade da solidão. Quem não é perdido não conhece a liberdade e não a ama. Quanto a mim, assumo a minha solidão.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Ah viver é tão desconfortável. Tudo aperta: o corpo exige, o espírito não pára, viver parece ter sono e não poder dormir - viver é incômodo. Não se pode andar nu nem de corpo nem de espírito.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Abandone-se, tente tudo suavemente, não se esforce por conseguir - esqueça completamente o que aconteceu e tudo voltará com naturalidade.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Ali estava uma mulher que a gulodice do mais fino sonho jamais poderia imaginar.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "E de tal modo haviam se disposto as coisas que o amor doloroso lhe pareceu felicidade.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Nada impediria que essa mulher que andava rolando os quadris subisse mais um degrau misterioso nos seus dias.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Oh Deus, eu que faço concorrência a mim mesma. Me detesto. Felizmente os outros gostam de mim. É uma tranqüilidade.Um sopro de vida.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Onde aprender a odiar para não morrer de amor?", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Perder-se significa ir achando e nem saber o que fazer do que se for achando.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Porém nenhuma vez mais se repetiu. Porque a verdade era um relance.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Quem sabe a que escuridão de amor pode chegar o carinho.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Sem entender jamais o que havia debom em ser gente, em sentir-se cansada, em diariamente falir; só os iniciados compreedem essa nuance de vício e esse refinamento de vida.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Sua sensibilidade incomodava sem ser dolorosa, como uma unha quebradiça.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "A mais premente necessidade de um ser humano era tornar-se um humano.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "O óbvio, Lorí, é a verdade mais difícil de se enxergar", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Nós ainda somos moços, podemos perder algum tempo sem perder a vida inteira.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Eu nunca fui livre na minha vida inteira. Por que dentro eu sempre me persegui. Eu me tornei intolerável para mim mesma.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "O que me mata é o cotidiano. Eu queria só exceções.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Oh Deus, eu que faço concorrência a mim mesma. Me detesto. Felizmente os outros gostam de mim. É uma tranqüilidade.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Ser um ser permissível a si mesmo é a glória de existir.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "É curioso como não sei dizer quem sou. Quer dizer, sei-o bem, mas não posso dizer. Sobretudo tenho medo de dizer porque no momento em que tento falar não só não exprimo o que sinto como o que sinto se transforma lentamente no que eu digo.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Liberdade é pouco. O que desejo ainda não tem nome.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Quem se recusa o prazer, quem se faz de monge, em qualquer sentido, é porque tem uma capacidade enorme para o prazer, uma capacidade perigosa – daí um temor maior ainda. Só quem guarda as armas a chave é quem receia atirar sobre todos", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "tenho medo de dizer porque no momento em que tento falar não só não exprimo o que sinto como o que sinto se transforma lentamente no que eu digo.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Tudo o que poderia existir, já existe. Nada mais pode ser criado senão revelado.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "A palavra é meu domínio sobre o mundo.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Sou brasileira naturalizada, quando, por questão de meses, poderia ser brasileira nata. Fiz da língua portuguesa a minha vida interior, o meu pensamento mais íntimo, usei-a para palavras de amor.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Ainda bem que sempre existe outro dia. E outros sonhos. E outros risos. E outras pessoas. E outras coisas.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Na arte, a inspiração tem um toque de magia, porque é uma coisa absoluta, inexplicável. Não creio que venha de fora pra dentro, de forças sobrenaturais. Suponho que emerge do mais profundo \"eu\" da pessoa, do inconsciente individual, coletivo e cósmico.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Não entendo, apenas sinto. Tenho medo de um dia entender e deixar de sentir.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Não se preocupe em entender. Viver ultrapassa qualquer entendimento.", Author = "Clarice Lispector" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Clarice_Lispector", Text = "Amar não acaba. É como se o mundo estivesse à minha espera. E eu vou ao encontro do que me espera.", Author = "Clarice Lispector" },
        };
    }
